package com.vandorlabs.neoforge.programmer;
import com.google.gson.*;
import com.vandorlabs.programmer.*;
import java.nio.file.*;
import net.minecraft.core.Direction;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
/** Released display selection and page-plane replay without mutable item retention or a render worker. */
final class ProgrammerJournalProjectionChecks {
 private static int checks;
 private static void need(boolean value,String reason){checks++;if(!value)throw new AssertionError("Programmer journal projection: "+reason);}
 static void run(ServerLevel level)throws Exception{var source=JsonParser.parseString(Files.readString(Path.of(System.getenv("VANDOR_PROGRAMMER_JOURNAL_REFERENCE")))).getAsJsonObject();need(source.get("golden").getAsString().equals("ae454c4f674210607b32c269c552545ea123e2b62bbb767503694c1f4c98fbc4"),"frozen Source journal");int views=0,unavailable=0,surface=0;for(var value:source.getAsJsonArray("views")){var row=value.getAsJsonObject();var raw=TagParser.parseTag(row.get("raw").getAsString());NativeProgrammerSnapshot snapshot;try{snapshot=NativeProgrammerSnapshot.prepare(raw,level.registryAccess());need(!row.get("unavailable").getAsBoolean(),"Vehicle snapshot accepted");}catch(IllegalArgumentException refusal){if(!row.get("unavailable").getAsBoolean())throw refusal;unavailable++;views++;continue;}var view=NativeProgrammerJournalView.prepare(snapshot.item(1),snapshot.item(2),snapshot.draft());need((view!=null)==row.has("view"),"Source Input/Output view existence");if(view!=null){var expected=row.getAsJsonObject("view");need(view.journal.title.equals(expected.get("title").getAsString())&&view.journal.source.equals(expected.get("source").getAsString())&&view.journal.key.equals(expected.get("key").getAsString()),"Source title/caption/key");var pages=expected.getAsJsonArray("pages");need(view.journal.pages.size()==pages.size(),"Source page count");for(int page=0;page<pages.size();page++){var actual=view.journal.pages.get(page);var reference=pages.get(page).getAsJsonObject();need(actual.entry==reference.get("entry").getAsInt()&&actual.lines.size()==reference.getAsJsonArray("lines").size(),"Source page entry/line count");for(int line=0;line<actual.lines.size();line++)need(actual.lines.get(line).equals(reference.getAsJsonArray("lines").get(line).getAsString()),"complete Source line");}var encoded=view.write();need(!encoded.toString().contains("OpaqueItem")&&!encoded.contains("Items"),"only authored text leaves ownership");var restored=NativeProgrammerJournalView.read(encoded);need(restored.journal.key.equals(view.journal.key)&&restored.page==0,"bounded public roundtrip");var last=view.withPage(Integer.MAX_VALUE);need(last.page==view.journal.pages.size()-1&&last.journal==view.journal&&last.withPage(-1).page==0,"navigation shares prepared immutable pagination");}views++;}
  var folder=Path.of(System.getenv("VANDOR_PROGRAMMER_GEOMETRY"));var mesh=ProgrammerPicking.read(Files.newInputStream(folder.resolve("static.obj")),Files.newInputStream(folder.resolve("screen.obj")));var plane=new ProgrammerJournalPlane(mesh);for(var value:source.getAsJsonArray("surface")){var row=value.getAsJsonObject();var layout=NativeProgrammerLayout.of(Direction.valueOf(row.get("facing").getAsString()));int x=7+layout.originX(),z=-11+layout.originZ();var a=row.getAsJsonArray("from");var b=row.getAsJsonArray("to");var hit=plane.hit(layout.transform(),x,80,z,a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble(),b.get(0).getAsDouble(),b.get(1).getAsDouble(),b.get(2).getAsDouble());need((hit!=null)==row.has("hit"),"front/back plane hit existence "+surface);if(hit!=null){var expected=row.getAsJsonArray("hit");need(Math.abs(hit.u-expected.get(0).getAsDouble())<1e-9&&Math.abs(hit.v-expected.get(1).getAsDouble())<1e-9&&hit.action()==row.get("action").getAsInt(),"exact pixel/button boundary "+surface);}var projected=plane.world(layout.transform(),x,80,z,row.get("u").getAsDouble(),row.get("v").getAsDouble());var expected=row.getAsJsonArray("point");need(Math.abs(projected.x-expected.get(0).getAsDouble())<1e-12&&Math.abs(projected.y-expected.get(1).getAsDouble())<1e-12&&Math.abs(projected.z-expected.get(2).getAsDouble())<1e-12,"source authored point");surface++;}need(views==288&&surface==1120&&unavailable==88,"whole supported/unavailable corpus");System.out.println("[vandorlabs][programmer-journal-projection] PASS SourceViews="+views+" unavailable="+unavailable+" surface="+surface+" checks="+checks);}
}
